import{_ as a,c as e,o as i,a2 as t}from"./chunks/framework.CP8b5y1j.js";const p=JSON.parse('{"title":"Agent 完整知识","description":"","frontmatter":{},"headers":[],"relativePath":"src/AI/Langchain/Agent.md","filePath":"src/AI/Langchain/Agent.md","lastUpdated":1782761745000}'),o={name:"src/AI/Langchain/Agent.md"};function r(n,l,d,h,c,u){return i(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="agent-完整知识" tabindex="-1">Agent 完整知识 <a class="header-anchor" href="#agent-完整知识" aria-label="Permalink to &quot;Agent 完整知识&quot;">​</a></h1><p>本文档是自包含归档版，完整汇总 Agent 概念、分步笔记、总复习，以及 Agent、RAG、Workflow、Tool、MCP 的关系。上传知识库后，不需要依赖原始文件夹。</p><hr><h2 id="agent-完全指南-从零理解到能判断" tabindex="-1">Agent 完全指南：从零理解到能判断 <a class="header-anchor" href="#agent-完全指南-从零理解到能判断" aria-label="Permalink to &quot;Agent 完全指南：从零理解到能判断&quot;">​</a></h2><hr><p>title: Agent 完全指南（从零理解到能判断） outline: deep</p><hr><h1 id="agent-完全指南-从零理解到能判断-1" tabindex="-1">Agent 完全指南：从零理解到能判断 <a class="header-anchor" href="#agent-完全指南-从零理解到能判断-1" aria-label="Permalink to &quot;Agent 完全指南：从零理解到能判断&quot;">​</a></h1><blockquote><p>一句话定位：读完这一篇，你能讲清楚 Agent 是什么、它和普通问答/Workflow/RAG/Tool/MCP 的区别，知道最小 Agent 由哪几部分组成、怎么运行，以及它最容易在哪里翻车。</p><p>阅读方式：第 1~4 章建立概念，第 5~6 章拆解最小 Agent 的结构和运行流程，第 7 章看常见模式，第 8 章看坑，第 9 章把所有相关概念一次理顺。</p></blockquote><h2 id="_0-这篇能带你到哪" tabindex="-1">0. 这篇能带你到哪 <a class="header-anchor" href="#_0-这篇能带你到哪" aria-label="Permalink to &quot;0. 这篇能带你到哪&quot;">​</a></h2><p>学完你应该能做到：</p><ol><li>一句话说清 Agent 和「普通问一句答一句」的区别</li><li>画出最小 Agent 的运行循环（判断 → 行动 → 观察 → 再判断）</li><li>分清一个系统到底是 Agent、Workflow，还是两者混合</li><li>知道 Agent 最容易在哪翻车，以及初学怎么避坑</li></ol><hr><h2 id="_1-什么是-agent" tabindex="-1">1. 什么是 Agent <a class="header-anchor" href="#_1-什么是-agent" aria-label="Permalink to &quot;1. 什么是 Agent&quot;">​</a></h2><p>一句话：</p><blockquote><p><strong>Agent = 不只是回答问题，而是会自己决定下一步做什么的系统。</strong></p></blockquote><p>对比一下：</p><table tabindex="0"><thead><tr><th></th><th>普通 LLM</th><th>Agent</th></tr></thead><tbody><tr><td>输入</td><td>一个问题</td><td>一个目标</td></tr><tr><td>输出</td><td>一个回答</td><td>一连串动作 + 最终结果</td></tr><tr><td>行为</td><td>问一句答一句</td><td>理解目标 → 决定要不要查/调工具 → 多步推进 → 给结果</td></tr></tbody></table><p>Agent 常见会做的事：思考下一步、调用工具、读文件、搜索知识库、调 API、写代码、执行多步任务。</p><p>它比普通问答复杂，是因为它通常<strong>循环</strong>做这些事：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看当前目标 → 决定下一步动作 → 调用工具 → 观察结果 → 再决定 → ... → 完成</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="agent-和-rag-的关系" tabindex="-1">Agent 和 RAG 的关系 <a class="header-anchor" href="#agent-和-rag-的关系" aria-label="Permalink to &quot;Agent 和 RAG 的关系&quot;">​</a></h3><ul><li><strong>RAG</strong> 是一种「先检索再回答」的<strong>方法</strong></li><li><strong>Agent</strong> 是一种「会自己决定步骤并调用工具」的<strong>系统</strong></li></ul><p>两者不相等，但 <strong>Agent 可以把 RAG 当成自己的一个工具</strong>。例如：Agent 判断问题需要查公司制度 → 触发 RAG 检索制度文档 → 根据结果继续完成任务。</p><p><strong>一个直观对比</strong>：</p><ul><li>纯 RAG：用户问「年假可以跨年吗？」→ 检索制度 → 根据文档回答。一步到位。</li><li>Agent：用户说「帮我总结请假制度，比较年假/病假/事假的区别，列成表格」→ 判断要查知识库 → 调 RAG 检索 → 提取三类信息 → 整理成表格 → 输出。多步完成。</li></ul><p>不是所有问答都需要 Agent。</p><hr><h2 id="_2-为什么-agent-需要工具" tabindex="-1">2. 为什么 Agent 需要工具 <a class="header-anchor" href="#_2-为什么-agent-需要工具" aria-label="Permalink to &quot;2. 为什么 Agent 需要工具&quot;">​</a></h2><p>一句话：</p><blockquote><p><strong>工具 = Agent 可以调用的外部能力。</strong></p></blockquote><p>工具不是「模型脑子里的知识」，而是运行时可以使用的额外能力，比如：搜索引擎、RAG 检索系统、数据库查询、文件读取、浏览器操作、代码执行器、计算器、邮件/日历/工单 API。</p><p><strong>哪些算工具，哪些不算</strong>：</p><ul><li>算工具：读文件、搜网页、查数据库、执行代码、RAG 检索器</li><li>不单独算工具：模型自己的推理、整理上下文、总结内容（这些是模型<strong>能力</strong>，不是独立工具）</li></ul><h3 id="为什么不能只靠大模型" tabindex="-1">为什么不能只靠大模型 <a class="header-anchor" href="#为什么不能只靠大模型" aria-label="Permalink to &quot;为什么不能只靠大模型&quot;">​</a></h3><p>大模型最擅长的是「根据输入生成文本」，但真实任务还需要查、算、读、写、调系统、执行操作。具体来说：</p><ol><li><strong>模型不能直接访问外部世界</strong>：看不到你的本地文件、最新网页、数据库、当前系统状态——没有工具就只能靠已有知识猜</li><li><strong>模型不能天然执行动作</strong>：你让它发邮件/查库/建工单/跑代码，它只会「描述怎么做」，不会真的做</li><li><strong>模型做精确计算和查询不稳定</strong>：数学、精确过滤、数据库查找更适合交给专门工具</li><li><strong>Agent 需要「先做，再看结果，再继续」</strong>：没有工具就没法真正行动并观察结果</li></ol><p>可以把 Agent 拆成两半：</p><blockquote><p><strong>大模型负责思考（理解目标、决定下一步），工具负责行动（执行能力、返回真实结果）。</strong></p><p><strong>没有工具的 Agent，往往只剩下「会说」，不一定真的「会做」。</strong></p></blockquote><hr><h2 id="_3-workflow-vs-agent" tabindex="-1">3. Workflow vs Agent <a class="header-anchor" href="#_3-workflow-vs-agent" aria-label="Permalink to &quot;3. Workflow vs Agent&quot;">​</a></h2><p>一句话：</p><blockquote><p><strong>Workflow = 预先设计好的固定流程。</strong></p></blockquote><p>如果一个系统是「先检索 → 再总结 → 再输出表格」，而且这个顺序是你<strong>提前写死</strong>的，那它更像 Workflow。</p><table tabindex="0"><thead><tr><th></th><th>Workflow</th><th>Agent</th></tr></thead><tbody><tr><td>流程</td><td>人提前设计好，步骤/顺序固定</td><td>给目标，系统自己决定下一步</td></tr><tr><td>灵活性</td><td>系统自主空间小</td><td>可能中途改策略、动态选工具</td></tr><tr><td>记忆法</td><td><strong>人定流程</strong></td><td><strong>模型定下一步</strong></td></tr></tbody></table><p><strong>关键认知</strong>：自动化 ≠ Agent。很多系统看起来都「自动完成任务」，但如果它只是严格按预设步骤走，那就是 Workflow，不是 Agent。很多号称 Agent 的产品，实际更像 Workflow。</p><hr><h2 id="_4-什么是-mcp" tabindex="-1">4. 什么是 MCP <a class="header-anchor" href="#_4-什么是-mcp" aria-label="Permalink to &quot;4. 什么是 MCP&quot;">​</a></h2><p>如果指的是 <code>Model Context Protocol</code>，那它<strong>不是一个具体工具</strong>，而是：</p><blockquote><p><strong>一种让模型或 Agent 连接外部能力的标准协议。</strong></p></blockquote><p>它解决的问题是：不同工具、资源、数据源，怎么用<strong>统一方式</strong>接给模型或 Agent。</p><p><strong>最好的类比</strong>：</p><blockquote><p><strong>工具像电器，MCP 像插座标准（接口标准）。</strong> 电器是具体能力，插座标准不是电器本身，但它决定了怎么统一接入。</p></blockquote><p><strong>为什么容易误以为 MCP 就是工具</strong>：因为实际用时你常看到「一个 MCP server 提供很多工具，模型通过 MCP 调用它们」。更准确的说法是：MCP server 里可以包含工具，但 MCP 本身是协议和连接方式。</p><p>一句话记忆：</p><blockquote><p><strong>Tool = 具体能力；MCP = 接入这些能力的标准方式。</strong></p></blockquote><hr><h2 id="_5-最小-agent-系统由什么组成" tabindex="-1">5. 最小 Agent 系统由什么组成 <a class="header-anchor" href="#_5-最小-agent-系统由什么组成" aria-label="Permalink to &quot;5. 最小 Agent 系统由什么组成&quot;">​</a></h2><p>一句话：</p><blockquote><p><strong>最小 Agent = 目标 + 模型 + 工具 + 决策循环 + 输出。</strong></p></blockquote><table tabindex="0"><thead><tr><th>部件</th><th>负责什么</th></tr></thead><tbody><tr><td>1. 目标</td><td>Agent 要完成什么（没有目标就没有后续行动）</td></tr><tr><td>2. 大模型</td><td>思考核心：理解目标、判断下一步、决定要不要调工具</td></tr><tr><td>3. 工具</td><td>提供外部能力：读文件、搜网页、调库、调 RAG、执行代码</td></tr><tr><td>4. 决策循环</td><td>和普通一次性问答最大的区别（见第 6 章）</td></tr><tr><td>5. 输出</td><td>任务完成时把最终结果交付给用户</td></tr></tbody></table><p>画成结构：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户目标 → 大模型判断 → 调工具 → 观察结果 → 继续判断 → 输出结果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>最小 Agent 不需要</strong>：多个 Agent、复杂记忆系统、长期状态管理、规划器、MCP、工作流编排平台。这些都可以后面再加。</p><blockquote><p>Agent 最小并不复杂。它的核心不是「高级」，而是「会判断并调用工具」。</p></blockquote><hr><h2 id="_6-agent-的最小运行流程" tabindex="-1">6. Agent 的最小运行流程 <a class="header-anchor" href="#_6-agent-的最小运行流程" aria-label="Permalink to &quot;6. Agent 的最小运行流程&quot;">​</a></h2><p>一句话：</p><blockquote><p><strong>接收目标 → 判断下一步 → 调用工具 → 观察结果 → 再判断 → 输出结果。</strong></p></blockquote><p>用一个具体任务走一遍——「帮我找出项目里有哪些 TypeScript 文件，并简单说明作用」：</p><ol><li><strong>接收目标</strong>：明确要完成什么</li><li><strong>判断下一步</strong>：该先做什么？要不要调工具？调哪个？→ 判断先用文件搜索工具找 <code>.ts</code></li><li><strong>调用工具</strong>：真的去执行查找（不是「说我要查」）</li><li><strong>观察结果</strong>：工具返回若干 <code>.ts</code> 文件路径</li><li><strong>再判断</strong>：这些够了吗？要不要读内容？→ 判断需要读文件才能总结</li><li><strong>继续调用工具</strong>：调文件读取工具，拿到内容</li><li><strong>输出最终结果</strong>：整理出有哪些文件、各自作用</li></ol><p><strong>核心循环</strong>：</p><blockquote><p><strong>判断 → 行动 → 观察 → 再判断。</strong></p></blockquote><p>其中「观察工具结果」这一步特别关键——Agent 不是盲目继续，而是要根据真实结果再决定下一步。这条循环就是 Agent 和普通一次性问答的本质差异。</p><hr><h2 id="_7-agent-的常见模式" tabindex="-1">7. Agent 的常见模式 <a class="header-anchor" href="#_7-agent-的常见模式" aria-label="Permalink to &quot;7. Agent 的常见模式&quot;">​</a></h2><blockquote><p>不是所有 Agent 都复杂，很多只是「目标 + 工具 + 决策循环」的不同组合。</p></blockquote><table tabindex="0"><thead><tr><th>模式</th><th>长什么样</th><th>例子</th></tr></thead><tbody><tr><td><strong>1. 单工具 Agent</strong></td><td>只有一个主要工具，模型判断何时调</td><td>「看看目录里有哪些 TS 文件」→ 调文件搜索 → 返回列表</td></tr><tr><td><strong>2. 多工具 Agent</strong></td><td>多个工具可选，需判断用哪个、按序调用</td><td>「总结 TS 文件作用」→ 搜文件 → 读内容 → 总结</td></tr><tr><td><strong>3. RAG 作为工具的 Agent</strong></td><td>需要查资料时调 RAG，拿结果再继续</td><td>「总结请假制度并对比年假/病假/事假」→ 调 RAG → 提取 → 对比</td></tr><tr><td><strong>4. Workflow 外壳 + Agent 核心</strong></td><td>外层流程固定，某环节内部交给 Agent 自主判断</td><td>固定「收问题→检查是否查库→输出」，其中「是否查、怎么查、是否继续查」交给 Agent</td></tr><tr><td><strong>5. 纯 Workflow（不是真 Agent）</strong></td><td>表面自动，但每步提前写死，无动态决策</td><td>永远走「查库→总结→输出表格」，不管问题是什么</td></tr></tbody></table><p><strong>怎么快速区分</strong>：</p><ul><li>只有固定步骤 → 更像 <strong>Workflow</strong></li><li>会动态选工具和下一步 → 更像 <strong>Agent</strong></li><li>固定流程里嵌一段动态决策 → <strong>混合模式</strong></li></ul><p><strong>初学建议的理解顺序</strong>：单工具 → 多工具 → RAG 作为工具 → Workflow+Agent 混合。<strong>不要一开始就想多 Agent 系统。</strong> 实际系统大多是混合模式，因为它更可控、更稳。</p><hr><h2 id="_8-agent-最容易踩的坑" tabindex="-1">8. Agent 最容易踩的坑 <a class="header-anchor" href="#_8-agent-最容易踩的坑" aria-label="Permalink to &quot;8. Agent 最容易踩的坑&quot;">​</a></h2><p>一句话：</p><blockquote><p><strong>Agent 最大的问题通常不是「不会回答」，而是「不会稳定地做事」。</strong></p></blockquote><table tabindex="0"><thead><tr><th>坑</th><th>是什么</th><th>为什么发生</th><th>后果</th></tr></thead><tbody><tr><td><strong>1. 选错工具</strong></td><td>该读文件却去查库</td><td>任务理解不清、工具描述不清、边界重叠</td><td>结果不准、浪费调用</td></tr><tr><td><strong>2. 不会用工具结果</strong></td><td>拿到结果却没真正利用</td><td>缺少明确的下一步判断</td><td>工具白调了</td></tr><tr><td><strong>3. 循环停不下来</strong></td><td>一直再查、再试、再补</td><td>没有清晰的完成条件</td><td>成本高、延迟大、体验差</td></tr><tr><td><strong>4. 该用 Workflow 却硬上 Agent</strong></td><td>固定流程够用却做成 Agent</td><td>觉得 Agent 更高级</td><td>系统更复杂、更难调试</td></tr><tr><td><strong>5. 工具太多决策乱</strong></td><td>工具太多模型选不对</td><td>工具描述太像、功能重复</td><td>切换混乱、错误率上升</td></tr><tr><td><strong>6. 目标太模糊</strong></td><td>不知道什么叫「完成」</td><td>任务定义太宽、没输出要求</td><td>循环过长、输出不稳</td></tr><tr><td><strong>7. 过度相信模型会自己规划好</strong></td><td>以为给够工具就能稳定完成复杂任务</td><td>对能力预期过高、缺约束</td><td>随机性大、难复现</td></tr></tbody></table><p><strong>初学避坑 5 条</strong>：</p><ol><li>工具不要一开始给太多</li><li>工具描述要清楚</li><li>任务目标要具体</li><li><strong>完成条件要明确</strong>（这是「循环停不下来」的解药）</li><li>能用 Workflow 解决的，不要先上 Agent</li></ol><p>最该刻进脑子的一句：</p><blockquote><p><strong>不要把「模型会思考」误解成「模型会稳定执行任务」。</strong></p><p>简单、可控、可观察，通常比「更智能」更重要。</p></blockquote><hr><h2 id="_9-总对比-agent-rag-workflow-tool-mcp" tabindex="-1">9. 总对比：Agent / RAG / Workflow / Tool / MCP <a class="header-anchor" href="#_9-总对比-agent-rag-workflow-tool-mcp" aria-label="Permalink to &quot;9. 总对比：Agent / RAG / Workflow / Tool / MCP&quot;">​</a></h2><p>最容易混的五个词，<strong>关键认知是：它们不在同一层。</strong></p><table tabindex="0"><thead><tr><th>概念</th><th>它是什么层</th><th>回答的问题</th><th>一句话</th></tr></thead><tbody><tr><td><strong>RAG</strong></td><td>方法</td><td>知识从哪里来</td><td>先检索资料，再生成回答</td></tr><tr><td><strong>Agent</strong></td><td>系统形态</td><td>任务怎么一步步完成</td><td>为完成目标，自己决定步骤并调用工具</td></tr><tr><td><strong>Workflow</strong></td><td>流程设计</td><td>流程怎么固定执行</td><td>预先设计好的固定流程</td></tr><tr><td><strong>Tool</strong></td><td>能力组件</td><td>系统具体能做什么动作</td><td>可调用的具体外部能力</td></tr><tr><td><strong>MCP</strong></td><td>接入协议</td><td>这些能力怎么标准化接进来</td><td>让能力标准化接入的协议层</td></tr></tbody></table><p><strong>它们之间的关系</strong>：</p><ul><li><strong>Agent 和 RAG</strong>：不相等，但 Agent 可以把 RAG 当工具</li><li><strong>Agent 和 Workflow</strong>：一个动态决策、一个固定流程，实际系统常混合</li><li><strong>Agent 和 Tool</strong>：Tool 是 Agent 做事的手脚，没有它 Agent 只能「说」</li><li><strong>Tool 和 MCP</strong>：Tool 是具体能力，MCP 是接入这些能力的协议标准</li><li><strong>RAG 和 Tool</strong>：在 Agent 系统里，RAG 常被包装成一个 Tool</li></ul><p><strong>判断速查</strong>：</p><ul><li>问「知识从哪里来？」→ 在谈 <strong>RAG</strong></li><li>问「任务怎么自己一步步完成？」→ 在谈 <strong>Agent</strong></li><li>问「步骤是不是提前写死？」→ 在谈 <strong>Workflow</strong></li><li>问「系统能调什么能力？」→ 在谈 <strong>Tool</strong></li><li>问「这些能力怎么统一接给模型？」→ 在谈 <strong>MCP</strong></li></ul><p><strong>四个常见误区</strong>：</p><ol><li>❌「RAG 就是 Agent」——RAG 是方法，Agent 是系统形态</li><li>❌「自动化流程就是 Agent」——固定步骤更可能只是 Workflow</li><li>❌「MCP 就是工具」——MCP 更像工具接入协议</li><li>❌「工具越多越是好 Agent」——工具太多反而让决策混乱</li></ol><p>压缩记忆：</p><blockquote><p><strong>RAG 管知识，Agent 管决策，Workflow 管固定流程，Tool 管行动能力，MCP 管接入标准。</strong></p></blockquote><hr><h2 id="_10-速记卡-背这些句子就够" tabindex="-1">10. 速记卡（背这些句子就够） <a class="header-anchor" href="#_10-速记卡-背这些句子就够" aria-label="Permalink to &quot;10. 速记卡（背这些句子就够）&quot;">​</a></h2><ul><li><code>Agent = 为完成目标，自己决定步骤并调用工具</code></li><li><code>Agent 管决策</code></li><li><code>普通模型偏单次回答，Agent 偏多步执行</code></li><li><code>最小 Agent = 目标 + 模型 + 工具 + 循环 + 输出</code></li><li><code>核心循环：判断 → 行动 → 观察 → 再判断</code></li><li><code>工具负责行动，模型负责思考</code></li><li><code>没有工具的 Agent 只能「说」，不能「做」</code></li><li><code>Workflow = 人定流程；Agent = 模型定下一步</code></li><li><code>自动化 ≠ Agent</code></li><li><code>Tool = 具体能力；MCP = 接入标准（电器 vs 插座）</code></li><li><code>RAG 可以是 Agent 的一个工具</code></li><li><code>Agent 最大问题是稳定执行，不只是回答</code></li><li><code>不要把「会思考」误解成「会稳定执行」</code></li><li><code>完成条件要明确，否则循环停不下来</code></li><li><code>能用 Workflow 解决的，就不要先上 Agent</code></li></ul><hr><h2 id="_11-术语表" tabindex="-1">11. 术语表 <a class="header-anchor" href="#_11-术语表" aria-label="Permalink to &quot;11. 术语表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th></tr></thead><tbody><tr><td>Agent</td><td>为完成目标、自己决定步骤并调用工具的系统</td></tr><tr><td>Tool（工具）</td><td>Agent 可调用的具体外部能力（读文件、搜网页、调 RAG 等）</td></tr><tr><td>决策循环</td><td>判断→行动→观察→再判断的多步推进过程</td></tr><tr><td>Workflow</td><td>预先设计好的固定流程</td></tr><tr><td>MCP</td><td>Model Context Protocol，让能力标准化接入模型/Agent 的协议</td></tr><tr><td>完成条件</td><td>判断任务何时算「做完」的标准，缺它循环会停不下来</td></tr><tr><td>单工具 / 多工具 Agent</td><td>按可用工具数量区分的 Agent 形态</td></tr><tr><td>混合模式</td><td>固定流程外壳里嵌入一段 Agent 动态决策</td></tr></tbody></table><hr><h2 id="agent-学习路径" tabindex="-1">Agent 学习路径 <a class="header-anchor" href="#agent-学习路径" aria-label="Permalink to &quot;Agent 学习路径&quot;">​</a></h2><h1 id="agent-学习路径-1" tabindex="-1">Agent 学习路径 <a class="header-anchor" href="#agent-学习路径-1" aria-label="Permalink to &quot;Agent 学习路径&quot;">​</a></h1><p>这个文件夹专门用于学习 Agent，不和 RAG 混在一起。</p><h2 id="推荐学习顺序" tabindex="-1">推荐学习顺序 <a class="header-anchor" href="#推荐学习顺序" aria-label="Permalink to &quot;推荐学习顺序&quot;">​</a></h2><ol><li><code>01-什么是Agent.md</code></li><li><code>02-为什么Agent需要工具.md</code></li><li><code>03-什么是Workflow.md</code></li><li><code>04-什么是MCP.md</code></li><li><code>05-最小Agent系统.md</code></li><li><code>06-Agent最小运行流程.md</code></li><li><code>07-Agent常见模式.md</code></li><li><code>08-Agent常见问题.md</code></li><li><code>09-Agent和RAG等概念总对比.md</code></li></ol><h2 id="学习方式" tabindex="-1">学习方式 <a class="header-anchor" href="#学习方式" aria-label="Permalink to &quot;学习方式&quot;">​</a></h2><ul><li>一次只看一个文件</li><li>每学完一步，都用自己的话复述</li><li>把自己不理解的点单独记下来</li></ul><h2 id="当前起点" tabindex="-1">当前起点 <a class="header-anchor" href="#当前起点" aria-label="Permalink to &quot;当前起点&quot;">​</a></h2><p>从 <code>01-什么是Agent.md</code> 开始。</p><hr><h2 id="第-1-步-什么是-agent" tabindex="-1">第 1 步：什么是 Agent <a class="header-anchor" href="#第-1-步-什么是-agent" aria-label="Permalink to &quot;第 1 步：什么是 Agent&quot;">​</a></h2><h1 id="第-1-步-什么是-agent-1" tabindex="-1">第 1 步：什么是 Agent <a class="header-anchor" href="#第-1-步-什么是-agent-1" aria-label="Permalink to &quot;第 1 步：什么是 Agent&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>Agent 是什么</li><li>Agent 和普通大模型调用有什么区别</li><li>Agent 和 RAG 有什么关系</li></ul><h2 id="先记住一句话" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>Agent = 不只是回答问题，而是会自己决定下一步做什么的系统</code></p><p>普通模型更像：</p><ul><li>你问一句</li><li>它答一句</li></ul><p>Agent 更像：</p><ul><li>它先理解目标</li><li>决定要不要查资料</li><li>决定要不要调用工具</li><li>决定是否继续下一步</li><li>最后再给你结果</li></ul><h2 id="最简单的区别" tabindex="-1">最简单的区别 <a class="header-anchor" href="#最简单的区别" aria-label="Permalink to &quot;最简单的区别&quot;">​</a></h2><h3 id="普通-llm" tabindex="-1">普通 LLM <a class="header-anchor" href="#普通-llm" aria-label="Permalink to &quot;普通 LLM&quot;">​</a></h3><p>输入：</p><ul><li>一个问题</li></ul><p>输出：</p><ul><li>一个回答</li></ul><h3 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>输入：</p><ul><li>一个目标</li></ul><p>输出：</p><ul><li>一连串动作和最终结果</li></ul><h2 id="agent-常见会做什么" tabindex="-1">Agent 常见会做什么 <a class="header-anchor" href="#agent-常见会做什么" aria-label="Permalink to &quot;Agent 常见会做什么&quot;">​</a></h2><p>一个 Agent 常见会有这些能力：</p><ul><li>思考下一步</li><li>调用工具</li><li>读取文件</li><li>搜索知识库</li><li>调 API</li><li>写代码</li><li>执行多步任务</li></ul><h2 id="agent-为什么比普通问答复杂" tabindex="-1">Agent 为什么比普通问答复杂 <a class="header-anchor" href="#agent-为什么比普通问答复杂" aria-label="Permalink to &quot;Agent 为什么比普通问答复杂&quot;">​</a></h2><p>因为它不是只做一次生成， 而是通常会循环做这些事：</p><ol><li>看当前目标</li><li>决定下一步动作</li><li>调用工具</li><li>观察结果</li><li>再决定下一步</li><li>直到完成任务</li></ol><h2 id="agent-和-rag-的关系-1" tabindex="-1">Agent 和 RAG 的关系 <a class="header-anchor" href="#agent-和-rag-的关系-1" aria-label="Permalink to &quot;Agent 和 RAG 的关系&quot;">​</a></h2><p>RAG 不是 Agent。</p><p>Agent 也不是 RAG。</p><p>更准确地说：</p><ul><li><code>RAG</code> 是一种“先检索再回答”的方法</li><li><code>Agent</code> 是一种“会自己决定步骤并调用工具”的系统</li></ul><p>但是：</p><p>Agent 可以把 RAG 当成自己的一个工具或一个步骤。</p><p>例如：</p><ul><li>Agent 先判断问题需要查公司制度</li><li>然后触发 RAG 去检索制度文档</li><li>再根据检索结果继续完成回答</li></ul><h2 id="一个直观例子" tabindex="-1">一个直观例子 <a class="header-anchor" href="#一个直观例子" aria-label="Permalink to &quot;一个直观例子&quot;">​</a></h2><h3 id="纯-rag" tabindex="-1">纯 RAG <a class="header-anchor" href="#纯-rag" aria-label="Permalink to &quot;纯 RAG&quot;">​</a></h3><p>用户问：</p><p>“年假可以跨年吗？”</p><p>系统：</p><ul><li>检索制度文档</li><li>根据文档回答</li></ul><h3 id="agent-1" tabindex="-1">Agent <a class="header-anchor" href="#agent-1" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>用户说：</p><p>“帮我总结请假制度，并告诉我年假、病假、事假的关键区别，再列成表格。”</p><p>Agent 可能会：</p><ol><li>判断需要查知识库</li><li>调用 RAG 检索相关制度</li><li>提取年假、病假、事假信息</li><li>整理成表格</li><li>输出最终结果</li></ol><p>这里就不只是“检索再回答”了，而是“多步完成任务”。</p><h2 id="你现在应该怎么学-agent" tabindex="-1">你现在应该怎么学 Agent <a class="header-anchor" href="#你现在应该怎么学-agent" aria-label="Permalink to &quot;你现在应该怎么学 Agent&quot;">​</a></h2><p>不要一上来就学复杂框架。</p><p>先记住 3 个核心点：</p><ol><li>Agent 有目标，不只是单次问题</li><li>Agent 会决定步骤</li><li>Agent 会调用工具</li></ol><h2 id="这一课你必须记住" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>Agent 是多步任务系统</li><li>Agent 会根据目标决定下一步动作</li><li>RAG 可以是 Agent 的一个工具</li><li>不是所有问答系统都需要 Agent</li></ul><h2 id="复习问题" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>Agent 和普通 LLM 调用最大的区别是什么？</li><li>为什么说 RAG 不等于 Agent？</li><li>Agent 为什么常常需要工具？</li><li>什么场景更像需要 Agent，而不只是 RAG？</li></ol><h2 id="动手目标" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己用一句话分别解释：</p><ul><li><code>RAG 是什么</code></li><li><code>Agent 是什么</code></li><li><code>RAG 和 Agent 的关系是什么</code></li></ul><hr><h2 id="第-2-步-为什么-agent-需要工具" tabindex="-1">第 2 步：为什么 Agent 需要工具 <a class="header-anchor" href="#第-2-步-为什么-agent-需要工具" aria-label="Permalink to &quot;第 2 步：为什么 Agent 需要工具&quot;">​</a></h2><h1 id="第-2-步-为什么-agent-需要工具-1" tabindex="-1">第 2 步：为什么 Agent 需要工具 <a class="header-anchor" href="#第-2-步-为什么-agent-需要工具-1" aria-label="Permalink to &quot;第 2 步：为什么 Agent 需要工具&quot;">​</a></h1><h2 id="学习目标-1" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-1" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>什么叫 Agent 的“工具”</li><li>为什么 Agent 往往不能只靠大模型本身</li><li>工具和普通文本生成的区别是什么</li></ul><h2 id="先记住一句话-1" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话-1" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>工具 = Agent 可以调用的外部能力</code></p><p>也就是说，工具不是“模型脑子里的知识”， 而是模型在运行过程中可以使用的额外能力。</p><h2 id="工具指的是什么" tabindex="-1">工具指的是什么 <a class="header-anchor" href="#工具指的是什么" aria-label="Permalink to &quot;工具指的是什么&quot;">​</a></h2><p>Agent 里的工具，通常指这些东西：</p><ul><li>搜索引擎</li><li>RAG 检索系统</li><li>数据库查询</li><li>文件读取</li><li>浏览器操作</li><li>代码执行器</li><li>计算器</li><li>邮件、日历、工单系统 API</li><li>第三方业务接口</li></ul><p>所以：</p><p>工具不一定是一个“软件界面”， 也可以是一个函数、一个 API、一个检索器、一个数据库查询接口。</p><h2 id="哪些算工具-哪些不算工具" tabindex="-1">哪些算工具，哪些不算工具 <a class="header-anchor" href="#哪些算工具-哪些不算工具" aria-label="Permalink to &quot;哪些算工具，哪些不算工具&quot;">​</a></h2><p>下面这些通常算工具：</p><ul><li>浏览器访问或网页搜索</li><li>文件读取</li><li>数据库查询</li><li>代码执行</li><li>RAG 检索器</li></ul><p>下面这些通常不单独算工具：</p><ul><li>模型自己的推理</li><li>模型整理上下文</li><li>模型总结内容</li></ul><p>也就是说：</p><ul><li>“读取文件”算工具</li><li>“搜索网页”算工具</li><li>“分析上下文”更像模型能力，不是独立工具</li></ul><h2 id="为什么不能只靠大模型-1" tabindex="-1">为什么不能只靠大模型 <a class="header-anchor" href="#为什么不能只靠大模型-1" aria-label="Permalink to &quot;为什么不能只靠大模型&quot;">​</a></h2><p>因为大模型本身最擅长的是：</p><p><code>根据输入生成文本</code></p><p>但很多真实任务不只是“说”，还需要：</p><ul><li>查</li><li>算</li><li>读</li><li>写</li><li>调系统</li><li>执行操作</li></ul><p>这些事情如果没有工具，模型通常做不好。</p><h2 id="agent-为什么往往需要工具" tabindex="-1">Agent 为什么往往需要工具 <a class="header-anchor" href="#agent-为什么往往需要工具" aria-label="Permalink to &quot;Agent 为什么往往需要工具&quot;">​</a></h2><h3 id="_1-模型不能直接访问外部世界" tabindex="-1">1. 模型不能直接访问外部世界 <a class="header-anchor" href="#_1-模型不能直接访问外部世界" aria-label="Permalink to &quot;1. 模型不能直接访问外部世界&quot;">​</a></h3><p>模型本身不会自动看到：</p><ul><li>你的本地文件</li><li>最新网页</li><li>数据库内容</li><li>当前系统状态</li></ul><p>如果没有工具，它就只能靠自己已有知识猜。</p><h3 id="_2-模型不能天然执行动作" tabindex="-1">2. 模型不能天然执行动作 <a class="header-anchor" href="#_2-模型不能天然执行动作" aria-label="Permalink to &quot;2. 模型不能天然执行动作&quot;">​</a></h3><p>你让它：</p><ul><li>发邮件</li><li>查数据库</li><li>新建工单</li><li>跑代码</li></ul><p>它只会“描述怎么做”， 不会真的做。</p><p>有了工具，它才能真正执行这些动作。</p><h3 id="_3-模型做精确计算和精确查询并不稳定" tabindex="-1">3. 模型做精确计算和精确查询并不稳定 <a class="header-anchor" href="#_3-模型做精确计算和精确查询并不稳定" aria-label="Permalink to &quot;3. 模型做精确计算和精确查询并不稳定&quot;">​</a></h3><p>例如：</p><ul><li>数学计算</li><li>精确过滤</li><li>数据库查找</li><li>报表汇总</li></ul><p>这些更适合交给专门工具完成。</p><h3 id="_4-agent-需要-先做-再看结果-再继续" tabindex="-1">4. Agent 需要“先做，再看结果，再继续” <a class="header-anchor" href="#_4-agent-需要-先做-再看结果-再继续" aria-label="Permalink to &quot;4. Agent 需要“先做，再看结果，再继续”&quot;">​</a></h3><p>很多任务不是一步完成的。</p><p>例如：</p><ol><li>先搜资料</li><li>看搜到什么</li><li>再决定下一步</li><li>可能继续查询或整理</li></ol><p>没有工具，Agent 就没法真正“行动并观察结果”。</p><h2 id="一个非常直观的例子" tabindex="-1">一个非常直观的例子 <a class="header-anchor" href="#一个非常直观的例子" aria-label="Permalink to &quot;一个非常直观的例子&quot;">​</a></h2><p>用户说：</p><p>“帮我看看这个项目里有哪些 TypeScript 文件，并总结它们的作用。”</p><p>如果没有工具：</p><ul><li>模型只能猜项目结构</li></ul><p>如果有工具：</p><ul><li>Agent 可以调用文件系统搜索</li><li>读取相关文件</li><li>再整理总结</li></ul><p>这就是“工具”的价值。</p><h2 id="agent-的核心不是只会想" tabindex="-1">Agent 的核心不是只会想 <a class="header-anchor" href="#agent-的核心不是只会想" aria-label="Permalink to &quot;Agent 的核心不是只会想&quot;">​</a></h2><p>你可以把 Agent 分成两部分：</p><ul><li><code>思考</code></li><li><code>行动</code></li></ul><p>大模型负责：</p><ul><li>理解目标</li><li>决定下一步</li></ul><p>工具负责：</p><ul><li>执行具体能力</li><li>返回真实结果</li></ul><p>所以：</p><p><code>没有工具的 Agent，往往只剩下“会说”，不一定真的会做。</code></p><h2 id="和-rag-的关系" tabindex="-1">和 RAG 的关系 <a class="header-anchor" href="#和-rag-的关系" aria-label="Permalink to &quot;和 RAG 的关系&quot;">​</a></h2><p>RAG 也可以被看成一种工具。</p><p>例如：</p><ul><li>Agent 发现问题需要查知识库</li><li>它就调用 RAG</li><li>RAG 返回相关文档</li><li>Agent 再继续完成任务</li></ul><p>所以在 Agent 系统里：</p><p><code>RAG 常常是工具之一</code></p><h2 id="这一课你必须记住-1" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-1" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>工具就是 Agent 可调用的外部能力</li><li>大模型擅长生成文本，不擅长独自完成所有真实任务</li><li>Agent 需要工具来访问信息、执行动作、获取结果</li><li>没有工具，Agent 往往只能“描述”，不能真正“完成”</li></ul><h2 id="复习问题-1" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-1" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>Agent 里的工具指的是什么？</li><li>为什么说大模型本身最擅长的是生成文本，而不是执行任务？</li><li>为什么 Agent 需要“行动并观察结果”？</li><li>RAG 为什么也可以被看作 Agent 的一种工具？</li></ol><h2 id="动手目标-1" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-1" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己举出 3 个你认为 Agent 常见会用到的工具，并说明它们分别解决什么问题。</p><hr><h2 id="第-3-步-什么是-workflow" tabindex="-1">第 3 步：什么是 Workflow <a class="header-anchor" href="#第-3-步-什么是-workflow" aria-label="Permalink to &quot;第 3 步：什么是 Workflow&quot;">​</a></h2><h1 id="第-3-步-什么是-workflow-1" tabindex="-1">第 3 步：什么是 Workflow <a class="header-anchor" href="#第-3-步-什么是-workflow-1" aria-label="Permalink to &quot;第 3 步：什么是 Workflow&quot;">​</a></h1><h2 id="学习目标-2" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-2" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>Workflow 是什么</li><li>Workflow 和 Agent 有什么区别</li><li>为什么很多系统其实更像 Workflow 而不是 Agent</li></ul><h2 id="先记住一句话-2" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话-2" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>Workflow = 预先设计好的固定流程</code></p><p>也就是说：</p><ul><li>第一步做什么</li><li>第二步做什么</li><li>第三步做什么</li></ul><p>这些通常是人提前写好的。</p><h2 id="最简单的理解" tabindex="-1">最简单的理解 <a class="header-anchor" href="#最简单的理解" aria-label="Permalink to &quot;最简单的理解&quot;">​</a></h2><p>如果一个系统是这样工作的：</p><ol><li>先检索资料</li><li>再总结内容</li><li>再输出表格</li></ol><p>而且这个顺序是你提前写死的， 那它更像 <code>Workflow</code>。</p><h2 id="workflow-的特点" tabindex="-1">Workflow 的特点 <a class="header-anchor" href="#workflow-的特点" aria-label="Permalink to &quot;Workflow 的特点&quot;">​</a></h2><ul><li>步骤固定</li><li>顺序固定或基本固定</li><li>每一步做什么是提前定义好的</li><li>系统自己决定的空间较小</li></ul><h2 id="agent-和-workflow-的区别" tabindex="-1">Agent 和 Workflow 的区别 <a class="header-anchor" href="#agent-和-workflow-的区别" aria-label="Permalink to &quot;Agent 和 Workflow 的区别&quot;">​</a></h2><h3 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h3><ul><li>人先把流程设计好</li><li>系统按流程执行</li></ul><h3 id="agent-2" tabindex="-1">Agent <a class="header-anchor" href="#agent-2" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><ul><li>给系统一个目标</li><li>系统自己决定下一步怎么做</li><li>可能中途改策略</li><li>可能动态选择工具</li></ul><h2 id="一个直观例子-1" tabindex="-1">一个直观例子 <a class="header-anchor" href="#一个直观例子-1" aria-label="Permalink to &quot;一个直观例子&quot;">​</a></h2><h3 id="workflow-1" tabindex="-1">Workflow <a class="header-anchor" href="#workflow-1" aria-label="Permalink to &quot;Workflow&quot;">​</a></h3><p>“收到问题后： 先查知识库， 再调用总结模块， 最后输出 Markdown 表格。”</p><p>这里步骤是固定的。</p><h3 id="agent-3" tabindex="-1">Agent <a class="header-anchor" href="#agent-3" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>“帮我完成这个任务。”</p><p>系统可能会先判断：</p><ul><li>要不要查知识库</li><li>要不要读文件</li><li>要不要调用浏览器</li><li>要不要再做下一轮查询</li></ul><p>这里步骤不是完全提前写死的。</p><h2 id="为什么很多人会混淆" tabindex="-1">为什么很多人会混淆 <a class="header-anchor" href="#为什么很多人会混淆" aria-label="Permalink to &quot;为什么很多人会混淆&quot;">​</a></h2><p>因为很多系统看起来都像“自动完成任务”， 但自动不等于 Agent。</p><p>如果它只是严格按预设步骤走， 那更像 Workflow。</p><h2 id="你现在应该怎么记" tabindex="-1">你现在应该怎么记 <a class="header-anchor" href="#你现在应该怎么记" aria-label="Permalink to &quot;你现在应该怎么记&quot;">​</a></h2><p>最短记忆法：</p><ul><li><code>Workflow = 人定流程</code></li><li><code>Agent = 模型定下一步</code></li></ul><h2 id="这一课你必须记住-2" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-2" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>Workflow 是固定流程</li><li>Agent 是动态决策系统</li><li>自动化系统不一定就是 Agent</li><li>很多所谓 Agent 产品，实际更像 Workflow</li></ul><h2 id="复习问题-2" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-2" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>Workflow 的核心特征是什么？</li><li>Agent 和 Workflow 最大的区别是什么？</li><li>为什么说“自动化”不等于“Agent”？</li></ol><h2 id="动手目标-2" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-2" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己举一个更像 Workflow 的例子，再举一个更像 Agent 的例子。</p><hr><h2 id="第-4-步-什么是-mcp" tabindex="-1">第 4 步：什么是 MCP <a class="header-anchor" href="#第-4-步-什么是-mcp" aria-label="Permalink to &quot;第 4 步：什么是 MCP&quot;">​</a></h2><h1 id="第-4-步-什么是-mcp-1" tabindex="-1">第 4 步：什么是 MCP <a class="header-anchor" href="#第-4-步-什么是-mcp-1" aria-label="Permalink to &quot;第 4 步：什么是 MCP&quot;">​</a></h1><h2 id="学习目标-3" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-3" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>MCP 是什么</li><li>MCP 和工具是什么关系</li><li>为什么说 MCP 不等于工具</li></ul><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><p>如果这里说的 MCP 是 <code>Model Context Protocol</code>， 那它不是一个具体工具， 更准确地说它是：</p><p><code>一种让模型或 Agent 连接外部能力的标准协议</code></p><h2 id="最简单的理解-1" tabindex="-1">最简单的理解 <a class="header-anchor" href="#最简单的理解-1" aria-label="Permalink to &quot;最简单的理解&quot;">​</a></h2><p>你可以把 MCP 想成：</p><ul><li>一套统一接口规范</li><li>一种“模型怎么接外部能力”的约定</li></ul><p>它解决的问题是：</p><p><code>不同工具、资源、数据源，怎么用统一方式接给模型或 Agent？</code></p><h2 id="mcp-和工具的关系" tabindex="-1">MCP 和工具的关系 <a class="header-anchor" href="#mcp-和工具的关系" aria-label="Permalink to &quot;MCP 和工具的关系&quot;">​</a></h2><p>最准确的说法是：</p><ul><li>MCP 不是工具本身</li><li>MCP 是让工具能够被模型统一调用的一种方式</li></ul><p>也就是说：</p><ul><li>浏览器可以是工具</li><li>文件系统可以是工具</li><li>数据库查询可以是工具</li><li>RAG 检索器可以是工具</li><li>MCP 是把这些能力暴露给模型的一种协议层</li></ul><h2 id="一个类比" tabindex="-1">一个类比 <a class="header-anchor" href="#一个类比" aria-label="Permalink to &quot;一个类比&quot;">​</a></h2><p>你可以这样记：</p><ul><li><code>工具</code> 像电器</li><li><code>MCP</code> 像插座标准或接口标准</li></ul><p>电器是具体能力， 插座标准不是电器本身， 但它决定了怎么统一接入。</p><h2 id="为什么会觉得-mcp-像工具" tabindex="-1">为什么会觉得 MCP 像工具 <a class="header-anchor" href="#为什么会觉得-mcp-像工具" aria-label="Permalink to &quot;为什么会觉得 MCP 像工具&quot;">​</a></h2><p>因为实际使用时，你经常会看到：</p><ul><li>一个 MCP server 提供很多工具</li><li>模型通过 MCP 去调用这些工具</li></ul><p>所以你会误以为：</p><p><code>MCP = 工具</code></p><p>但更准确的理解是：</p><ul><li><code>MCP server</code> 里可以包含工具</li><li><code>MCP</code> 本身是协议和连接方式</li></ul><h2 id="在-agent-里怎么理解-mcp" tabindex="-1">在 Agent 里怎么理解 MCP <a class="header-anchor" href="#在-agent-里怎么理解-mcp" aria-label="Permalink to &quot;在 Agent 里怎么理解 MCP&quot;">​</a></h2><p>如果 Agent 需要：</p><ul><li>读文件</li><li>查数据库</li><li>搜网页</li><li>执行代码</li></ul><p>那 MCP 可以作为一层统一接入方式， 让这些工具能力以标准形式暴露给 Agent。</p><h2 id="你现在应该怎么记-1" tabindex="-1">你现在应该怎么记 <a class="header-anchor" href="#你现在应该怎么记-1" aria-label="Permalink to &quot;你现在应该怎么记&quot;">​</a></h2><p>最短记忆法：</p><ul><li><code>工具 = 具体能力</code></li><li><code>MCP = 接入这些能力的标准方式</code></li></ul><h2 id="这一课你必须记住-3" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-3" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>MCP 不是具体工具</li><li>MCP 是协议或标准接口层</li><li>工具可以通过 MCP 暴露给模型或 Agent</li><li>所以“MCP 是不是工具”更准确的回答是“不是，它更像工具接入标准”</li></ul><h2 id="复习问题-3" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-3" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>为什么说 MCP 不是具体工具？</li><li>MCP 和工具最核心的区别是什么？</li><li>为什么 MCP server 容易让人误以为 MCP 就是工具？</li></ol><h2 id="动手目标-3" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-3" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己用一句话分别解释：</p><ul><li><code>工具是什么</code></li><li><code>MCP是什么</code></li><li><code>它们的关系是什么</code></li></ul><hr><h2 id="第-5-步-最小-agent-系统需要哪些部分" tabindex="-1">第 5 步：最小 Agent 系统需要哪些部分 <a class="header-anchor" href="#第-5-步-最小-agent-系统需要哪些部分" aria-label="Permalink to &quot;第 5 步：最小 Agent 系统需要哪些部分&quot;">​</a></h2><h1 id="第-5-步-最小-agent-系统需要哪些部分-1" tabindex="-1">第 5 步：最小 Agent 系统需要哪些部分 <a class="header-anchor" href="#第-5-步-最小-agent-系统需要哪些部分-1" aria-label="Permalink to &quot;第 5 步：最小 Agent 系统需要哪些部分&quot;">​</a></h1><h2 id="学习目标-4" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-4" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>一个最小 Agent 系统最少要有什么</li><li>每一部分分别负责什么</li><li>为什么不是所有系统都需要复杂 Agent 框架</li></ul><h2 id="先记住一句话-3" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话-3" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>最小 Agent = 目标 + 模型 + 工具 + 决策循环 + 输出</code></p><h2 id="_1-目标" tabindex="-1">1. 目标 <a class="header-anchor" href="#_1-目标" aria-label="Permalink to &quot;1. 目标&quot;">​</a></h2><p>Agent 先要知道：</p><ul><li>你想让它完成什么</li></ul><p>例如：</p><ul><li>“帮我总结这个文件夹里的 TS 文件作用”</li><li>“帮我查知识库并整理成表格”</li></ul><p>没有目标，就没有后续行动。</p><h2 id="_2-大模型" tabindex="-1">2. 大模型 <a class="header-anchor" href="#_2-大模型" aria-label="Permalink to &quot;2. 大模型&quot;">​</a></h2><p>大模型负责：</p><ul><li>理解目标</li><li>判断下一步</li><li>决定要不要调用工具</li><li>根据结果继续推进</li></ul><p>它是 Agent 的“思考核心”。</p><h2 id="_3-工具" tabindex="-1">3. 工具 <a class="header-anchor" href="#_3-工具" aria-label="Permalink to &quot;3. 工具&quot;">​</a></h2><p>工具负责提供外部能力，例如：</p><ul><li>读取文件</li><li>搜索网页</li><li>调数据库</li><li>调 RAG 检索器</li><li>执行代码</li></ul><p>没有工具，Agent 往往只能“说”，不能真正“做”。</p><h2 id="_4-决策循环" tabindex="-1">4. 决策循环 <a class="header-anchor" href="#_4-决策循环" aria-label="Permalink to &quot;4. 决策循环&quot;">​</a></h2><p>这是 Agent 和普通一次性问答最大的区别。</p><p>Agent 通常不是一步完成，而是循环做：</p><ol><li>看当前目标</li><li>判断下一步</li><li>调用工具</li><li>观察结果</li><li>再决定下一步</li></ol><p>这就是最小的 Agent loop。</p><h2 id="_5-输出" tabindex="-1">5. 输出 <a class="header-anchor" href="#_5-输出" aria-label="Permalink to &quot;5. 输出&quot;">​</a></h2><p>当 Agent 觉得任务已经完成时， 需要把最终结果返回给用户。</p><p>例如：</p><ul><li>一段总结</li><li>一张表格</li><li>一次查询结果</li><li>一个执行完成的状态</li></ul><h2 id="画成最简单结构" tabindex="-1">画成最简单结构 <a class="header-anchor" href="#画成最简单结构" aria-label="Permalink to &quot;画成最简单结构&quot;">​</a></h2><p>你可以把最小 Agent 画成：</p><p>用户目标 -&gt; 大模型判断 -&gt; 调工具 -&gt; 观察结果 -&gt; 继续判断 -&gt; 输出结果</p><h2 id="一个非常小的例子" tabindex="-1">一个非常小的例子 <a class="header-anchor" href="#一个非常小的例子" aria-label="Permalink to &quot;一个非常小的例子&quot;">​</a></h2><p>用户说：</p><p>“帮我看看这个目录里有哪些 TypeScript 文件。”</p><p>最小 Agent 可以这样工作：</p><ol><li>接收目标</li><li>判断需要用文件搜索工具</li><li>调用工具查找 <code>.ts</code> 文件</li><li>拿到结果</li><li>整理成回答</li><li>返回给用户</li></ol><p>这已经是一个很小的 Agent 系统了。</p><h2 id="不是必须有的东西" tabindex="-1">不是必须有的东西 <a class="header-anchor" href="#不是必须有的东西" aria-label="Permalink to &quot;不是必须有的东西&quot;">​</a></h2><p>很多人一提 Agent 就想到很复杂的系统， 但最小 Agent 不一定需要：</p><ul><li>多个 Agent</li><li>复杂记忆系统</li><li>长期状态管理</li><li>规划器</li><li>MCP</li><li>工作流编排平台</li></ul><p>这些都可以后面再加。</p><h2 id="你现在应该怎么记-2" tabindex="-1">你现在应该怎么记 <a class="header-anchor" href="#你现在应该怎么记-2" aria-label="Permalink to &quot;你现在应该怎么记&quot;">​</a></h2><p>最短记忆法：</p><ul><li><code>目标</code>：要干什么</li><li><code>模型</code>：负责判断</li><li><code>工具</code>：负责行动</li><li><code>循环</code>：负责多步推进</li><li><code>输出</code>：负责交付结果</li></ul><h2 id="这一课你必须记住-4" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-4" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>Agent 最小并不复杂</li><li>它的核心不是“高级”，而是“会判断并调用工具”</li><li>Agent 和普通 LLM 最大区别在于多步决策循环</li><li>工具和循环是 Agent 系统的关键</li></ul><h2 id="复习问题-4" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-4" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>一个最小 Agent 系统最少要有哪些部分？</li><li>为什么说“决策循环”是 Agent 的关键？</li><li>为什么没有工具的 Agent 往往只能“说”？</li><li>为什么不是所有 Agent 都必须上复杂框架？</li></ol><h2 id="动手目标-4" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-4" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己举一个最小 Agent 例子，并指出：</p><ul><li>目标是什么</li><li>模型负责什么</li><li>工具是什么</li><li>最终输出是什么</li></ul><hr><h2 id="第-6-步-agent-的最小运行流程" tabindex="-1">第 6 步：Agent 的最小运行流程 <a class="header-anchor" href="#第-6-步-agent-的最小运行流程" aria-label="Permalink to &quot;第 6 步：Agent 的最小运行流程&quot;">​</a></h2><h1 id="第-6-步-agent-的最小运行流程-1" tabindex="-1">第 6 步：Agent 的最小运行流程 <a class="header-anchor" href="#第-6-步-agent-的最小运行流程-1" aria-label="Permalink to &quot;第 6 步：Agent 的最小运行流程&quot;">​</a></h1><h2 id="学习目标-5" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-5" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>一个最小 Agent 是怎么一步一步运行的</li><li>它和普通一次性问答有什么区别</li><li>“判断 -&gt; 调工具 -&gt; 看结果 -&gt; 再判断” 这条链路是怎么形成的</li></ul><h2 id="先记住一句话-4" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话-4" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>Agent 的最小运行流程 = 接收目标 -&gt; 判断下一步 -&gt; 调用工具 -&gt; 观察结果 -&gt; 再判断 -&gt; 输出结果</code></p><h2 id="最小流程拆开看" tabindex="-1">最小流程拆开看 <a class="header-anchor" href="#最小流程拆开看" aria-label="Permalink to &quot;最小流程拆开看&quot;">​</a></h2><h3 id="_1-接收目标" tabindex="-1">1. 接收目标 <a class="header-anchor" href="#_1-接收目标" aria-label="Permalink to &quot;1. 接收目标&quot;">​</a></h3><p>用户先给 Agent 一个任务。</p><p>例如：</p><ul><li>“帮我看看这个项目里有哪些 TypeScript 文件”</li></ul><p>这一步的作用是：</p><ul><li>让 Agent 明确自己要完成什么</li></ul><h2 id="_2-判断下一步" tabindex="-1">2. 判断下一步 <a class="header-anchor" href="#_2-判断下一步" aria-label="Permalink to &quot;2. 判断下一步&quot;">​</a></h2><p>大模型先思考：</p><ul><li>这个任务该先做什么</li><li>要不要调用工具</li><li>如果要调用，应该调用哪个工具</li></ul><p>例如在这个任务里，它可能判断：</p><ul><li>先用文件搜索工具找 <code>.ts</code> 文件</li></ul><h2 id="_3-调用工具" tabindex="-1">3. 调用工具 <a class="header-anchor" href="#_3-调用工具" aria-label="Permalink to &quot;3. 调用工具&quot;">​</a></h2><p>Agent 根据判断结果，去调用对应工具。</p><p>例如：</p><ul><li>调用文件搜索工具</li></ul><p>这一步不是“说我要查文件”， 而是真的去执行查找动作。</p><h2 id="_4-观察结果" tabindex="-1">4. 观察结果 <a class="header-anchor" href="#_4-观察结果" aria-label="Permalink to &quot;4. 观察结果&quot;">​</a></h2><p>工具执行完后，会返回结果给 Agent。</p><p>例如：</p><ul><li>返回若干 <code>.ts</code> 文件路径</li></ul><p>这一步很关键，因为 Agent 不是盲目继续， 而是要根据真实结果再决定下一步。</p><h2 id="_5-再判断下一步" tabindex="-1">5. 再判断下一步 <a class="header-anchor" href="#_5-再判断下一步" aria-label="Permalink to &quot;5. 再判断下一步&quot;">​</a></h2><p>Agent 看完结果后继续思考：</p><ul><li>这些文件够了吗</li><li>要不要继续读文件内容</li><li>要不要再调用别的工具</li></ul><p>例如它可能判断：</p><ul><li>需要读取这些文件，才能总结它们的作用</li></ul><h2 id="_6-继续调用工具" tabindex="-1">6. 继续调用工具 <a class="header-anchor" href="#_6-继续调用工具" aria-label="Permalink to &quot;6. 继续调用工具&quot;">​</a></h2><p>于是 Agent 再调用：</p><ul><li>文件读取工具</li></ul><p>然后继续拿结果。</p><h2 id="_7-输出最终结果" tabindex="-1">7. 输出最终结果 <a class="header-anchor" href="#_7-输出最终结果" aria-label="Permalink to &quot;7. 输出最终结果&quot;">​</a></h2><p>当 Agent 觉得任务已经完成， 就把最终结果返回给用户。</p><p>例如：</p><ul><li>这些 TS 文件有哪些</li><li>每个文件大概负责什么</li></ul><h2 id="画成最简单流程图" tabindex="-1">画成最简单流程图 <a class="header-anchor" href="#画成最简单流程图" aria-label="Permalink to &quot;画成最简单流程图&quot;">​</a></h2><p>你可以把它画成：</p><p>用户目标 -&gt; 模型判断 -&gt; 工具执行 -&gt; 返回结果 -&gt; 模型再判断 -&gt; 继续执行或结束 -&gt; 输出结果</p><h2 id="和普通问答的区别" tabindex="-1">和普通问答的区别 <a class="header-anchor" href="#和普通问答的区别" aria-label="Permalink to &quot;和普通问答的区别&quot;">​</a></h2><h3 id="普通问答" tabindex="-1">普通问答 <a class="header-anchor" href="#普通问答" aria-label="Permalink to &quot;普通问答&quot;">​</a></h3><ul><li>用户问一次</li><li>模型答一次</li></ul><h3 id="agent-4" tabindex="-1">Agent <a class="header-anchor" href="#agent-4" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><ul><li>用户给目标</li><li>模型判断</li><li>工具执行</li><li>模型再判断</li><li>可能反复几轮</li><li>最后才输出</li></ul><h2 id="一个非常小的例子-1" tabindex="-1">一个非常小的例子 <a class="header-anchor" href="#一个非常小的例子-1" aria-label="Permalink to &quot;一个非常小的例子&quot;">​</a></h2><p>任务：</p><p>“帮我找出项目里有哪些 TypeScript 文件，并简单说明它们的作用。”</p><p>可能流程：</p><ol><li>接收任务</li><li>判断要先找 <code>.ts</code> 文件</li><li>调用文件搜索工具</li><li>得到文件列表</li><li>判断还需要读文件内容</li><li>调用文件读取工具</li><li>读取内容后整理总结</li><li>输出答案</li></ol><h2 id="你现在应该怎么记-3" tabindex="-1">你现在应该怎么记 <a class="header-anchor" href="#你现在应该怎么记-3" aria-label="Permalink to &quot;你现在应该怎么记&quot;">​</a></h2><p>最短记忆法：</p><ul><li><code>先定目标</code></li><li><code>再做判断</code></li><li><code>再调工具</code></li><li><code>拿结果继续判断</code></li><li><code>直到完成</code></li></ul><h2 id="这一课你必须记住-5" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-5" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>Agent 不是一步完成，而是多步推进</li><li>工具执行后的“结果反馈”非常关键</li><li>Agent 的核心循环是“判断 -&gt; 行动 -&gt; 观察 -&gt; 再判断”</li><li>这条循环就是 Agent 和普通问答的核心差异之一</li></ul><h2 id="复习问题-5" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-5" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>Agent 的最小运行流程有哪些步骤？</li><li>为什么“观察工具结果”这一步很关键？</li><li>Agent 和普通一次性问答最大的流程差异是什么？</li></ol><h2 id="动手目标-5" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-5" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己用一句话解释：</p><ul><li>为什么 Agent 需要“再判断”这一步</li></ul><hr><h2 id="第-7-步-agent-的常见模式" tabindex="-1">第 7 步：Agent 的常见模式 <a class="header-anchor" href="#第-7-步-agent-的常见模式" aria-label="Permalink to &quot;第 7 步：Agent 的常见模式&quot;">​</a></h2><h1 id="第-7-步-agent-的常见模式-1" tabindex="-1">第 7 步：Agent 的常见模式 <a class="header-anchor" href="#第-7-步-agent-的常见模式-1" aria-label="Permalink to &quot;第 7 步：Agent 的常见模式&quot;">​</a></h1><h2 id="学习目标-6" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-6" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>常见 Agent 模式有哪些</li><li>它们分别适合什么场景</li><li>为什么很多系统其实不是“纯 Agent”，而是混合模式</li></ul><h2 id="先记住一句话-5" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话-5" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>不是所有 Agent 都很复杂，很多 Agent 只是“目标 + 工具 + 决策循环”的不同组合。</code></p><h2 id="模式-1-单工具-agent" tabindex="-1">模式 1：单工具 Agent <a class="header-anchor" href="#模式-1-单工具-agent" aria-label="Permalink to &quot;模式 1：单工具 Agent&quot;">​</a></h2><h3 id="长什么样" tabindex="-1">长什么样 <a class="header-anchor" href="#长什么样" aria-label="Permalink to &quot;长什么样&quot;">​</a></h3><ul><li>只有一个主要工具</li><li>模型负责判断何时调用它</li><li>调完之后整理结果输出</li></ul><h3 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h3><p>用户说：</p><p>“帮我看看这个目录里有哪些 TypeScript 文件。”</p><p>系统：</p><ol><li>判断需要文件搜索工具</li><li>调工具</li><li>返回文件列表</li></ol><h3 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h3><ul><li>结构最简单</li><li>很适合入门</li><li>任务边界清晰</li></ul><h2 id="模式-2-多工具-agent" tabindex="-1">模式 2：多工具 Agent <a class="header-anchor" href="#模式-2-多工具-agent" aria-label="Permalink to &quot;模式 2：多工具 Agent&quot;">​</a></h2><h3 id="长什么样-1" tabindex="-1">长什么样 <a class="header-anchor" href="#长什么样-1" aria-label="Permalink to &quot;长什么样&quot;">​</a></h3><ul><li>有多个工具可选</li><li>模型需要判断该用哪个工具</li><li>可能按顺序调用多个工具</li></ul><h3 id="例子-1" tabindex="-1">例子 <a class="header-anchor" href="#例子-1" aria-label="Permalink to &quot;例子&quot;">​</a></h3><p>用户说：</p><p>“帮我总结这个项目里的 TS 文件，并说明每个文件做什么。”</p><p>系统可能会：</p><ol><li>调文件搜索工具找 <code>.ts</code> 文件</li><li>调文件读取工具看内容</li><li>再整理总结</li></ol><h3 id="特点-1" tabindex="-1">特点 <a class="header-anchor" href="#特点-1" aria-label="Permalink to &quot;特点&quot;">​</a></h3><ul><li>比单工具 Agent 更常见</li><li>决策难度更高</li><li>需要处理工具选择问题</li></ul><h2 id="模式-3-rag-作为工具的-agent" tabindex="-1">模式 3：RAG 作为工具的 Agent <a class="header-anchor" href="#模式-3-rag-作为工具的-agent" aria-label="Permalink to &quot;模式 3：RAG 作为工具的 Agent&quot;">​</a></h2><h3 id="长什么样-2" tabindex="-1">长什么样 <a class="header-anchor" href="#长什么样-2" aria-label="Permalink to &quot;长什么样&quot;">​</a></h3><ul><li>Agent 自己不直接懂所有知识</li><li>当需要查资料时，调用 RAG</li><li>拿到检索结果后再继续完成任务</li></ul><h3 id="例子-2" tabindex="-1">例子 <a class="header-anchor" href="#例子-2" aria-label="Permalink to &quot;例子&quot;">​</a></h3><p>用户说：</p><p>“帮我总结请假制度，并比较年假、病假、事假的区别。”</p><p>系统可能会：</p><ol><li>判断需要查知识库</li><li>调 RAG 检索制度文档</li><li>提取关键信息</li><li>整理成对比结果</li></ol><h3 id="特点-2" tabindex="-1">特点 <a class="header-anchor" href="#特点-2" aria-label="Permalink to &quot;特点&quot;">​</a></h3><ul><li>很常见</li><li>把 RAG 当成 Agent 的一个能力模块</li><li>适合“先查资料，再做进一步整理”的任务</li></ul><h2 id="模式-4-workflow-外壳-agent-核心" tabindex="-1">模式 4：Workflow 外壳 + Agent 核心 <a class="header-anchor" href="#模式-4-workflow-外壳-agent-核心" aria-label="Permalink to &quot;模式 4：Workflow 外壳 + Agent 核心&quot;">​</a></h2><h3 id="长什么样-3" tabindex="-1">长什么样 <a class="header-anchor" href="#长什么样-3" aria-label="Permalink to &quot;长什么样&quot;">​</a></h3><ul><li>外层流程是固定的</li><li>某个环节内部交给 Agent 自主判断</li></ul><h3 id="例子-3" tabindex="-1">例子 <a class="header-anchor" href="#例子-3" aria-label="Permalink to &quot;例子&quot;">​</a></h3><p>固定流程：</p><ol><li>先接收用户问题</li><li>再检查是否要查知识库</li><li>再输出结果</li></ol><p>其中“检查是否要查知识库、如何查、是否继续查”这一段， 交给 Agent 自己判断。</p><h3 id="特点-3" tabindex="-1">特点 <a class="header-anchor" href="#特点-3" aria-label="Permalink to &quot;特点&quot;">​</a></h3><ul><li>这是实际系统里很常见的混合模式</li><li>更容易控制风险</li><li>比纯 Agent 更稳</li></ul><h2 id="模式-5-纯-workflow-不是真正-agent" tabindex="-1">模式 5：纯 Workflow，不是真正 Agent <a class="header-anchor" href="#模式-5-纯-workflow-不是真正-agent" aria-label="Permalink to &quot;模式 5：纯 Workflow，不是真正 Agent&quot;">​</a></h2><h3 id="长什么样-4" tabindex="-1">长什么样 <a class="header-anchor" href="#长什么样-4" aria-label="Permalink to &quot;长什么样&quot;">​</a></h3><ul><li>表面上也在自动完成任务</li><li>但每一步都是提前写死的</li><li>没有真正动态决策</li></ul><h3 id="例子-4" tabindex="-1">例子 <a class="header-anchor" href="#例子-4" aria-label="Permalink to &quot;例子&quot;">​</a></h3><p>系统永远执行：</p><ol><li>查知识库</li><li>总结内容</li><li>输出表格</li></ol><p>无论问题是什么都这么走。</p><h3 id="特点-4" tabindex="-1">特点 <a class="header-anchor" href="#特点-4" aria-label="Permalink to &quot;特点&quot;">​</a></h3><ul><li>可控</li><li>好调试</li><li>但不算真正意义上的 Agent</li></ul><h2 id="你现在应该怎么区分" tabindex="-1">你现在应该怎么区分 <a class="header-anchor" href="#你现在应该怎么区分" aria-label="Permalink to &quot;你现在应该怎么区分&quot;">​</a></h2><p>最短判断法：</p><ul><li><code>只有固定步骤</code>：更像 Workflow</li><li><code>会动态选工具和下一步</code>：更像 Agent</li><li><code>固定流程里嵌一段动态决策</code>：混合模式</li></ul><h2 id="初学者最该先理解哪几个" tabindex="-1">初学者最该先理解哪几个 <a class="header-anchor" href="#初学者最该先理解哪几个" aria-label="Permalink to &quot;初学者最该先理解哪几个&quot;">​</a></h2><p>建议顺序：</p><ol><li>单工具 Agent</li><li>多工具 Agent</li><li>RAG 作为工具的 Agent</li><li>Workflow + Agent 混合模式</li></ol><p>不要一开始就去想多 Agent 系统。</p><h2 id="这一课你必须记住-6" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-6" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>Agent 有很多模式，不是只有一种形态</li><li>多数实际系统不是纯 Agent，而是混合模式</li><li>RAG 很常作为 Agent 的一个工具</li><li>Workflow 和 Agent 的边界要分清</li></ul><h2 id="复习问题-6" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-6" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>单工具 Agent 和多工具 Agent 的区别是什么？</li><li>为什么说 RAG 常常是 Agent 的一个工具？</li><li>为什么很多真实系统会用 Workflow + Agent 混合模式？</li><li>为什么“固定步骤自动化”不一定是 Agent？</li></ol><h2 id="动手目标-6" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-6" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己分别举一个例子，说明下面四种模式：</p><ul><li>单工具 Agent</li><li>多工具 Agent</li><li>RAG 作为工具的 Agent</li><li>Workflow + Agent 混合模式</li></ul><hr><h2 id="第-8-步-agent-最常见的问题" tabindex="-1">第 8 步：Agent 最常见的问题 <a class="header-anchor" href="#第-8-步-agent-最常见的问题" aria-label="Permalink to &quot;第 8 步：Agent 最常见的问题&quot;">​</a></h2><h1 id="第-8-步-agent-最常见的问题-1" tabindex="-1">第 8 步：Agent 最常见的问题 <a class="header-anchor" href="#第-8-步-agent-最常见的问题-1" aria-label="Permalink to &quot;第 8 步：Agent 最常见的问题&quot;">​</a></h1><h2 id="学习目标-7" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-7" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>理解：</p><ul><li>Agent 最容易出问题的地方有哪些</li><li>为什么这些问题会出现</li><li>初学时应该怎么避免</li></ul><h2 id="先记住一句话-6" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话-6" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>Agent 最大的问题通常不是“不会回答”，而是“不会稳定地做事”。</code></p><h2 id="问题-1-选错工具" tabindex="-1">问题 1：选错工具 <a class="header-anchor" href="#问题-1-选错工具" aria-label="Permalink to &quot;问题 1：选错工具&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>Agent 有多个工具时，可能挑错工具。</p><p>例如：</p><ul><li>明明该读文件，却去查知识库</li><li>明明该查数据库，却只做网页搜索</li></ul><h3 id="为什么会发生" tabindex="-1">为什么会发生 <a class="header-anchor" href="#为什么会发生" aria-label="Permalink to &quot;为什么会发生&quot;">​</a></h3><ul><li>任务理解不清</li><li>工具描述不清</li><li>工具边界重叠</li></ul><h3 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h3><ul><li>结果不准确</li><li>浪费调用次数</li><li>任务变慢</li></ul><h2 id="问题-2-工具调用后不会正确使用结果" tabindex="-1">问题 2：工具调用后不会正确使用结果 <a class="header-anchor" href="#问题-2-工具调用后不会正确使用结果" aria-label="Permalink to &quot;问题 2：工具调用后不会正确使用结果&quot;">​</a></h2><h3 id="是什么-1" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-1" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>Agent 调完工具后，拿到了结果， 但没有真正理解或正确利用这些结果。</p><p>例如：</p><ul><li>找到了文件列表，却没有继续读内容</li><li>检索到了制度文档，却回答时没用到关键句</li></ul><h3 id="为什么会发生-1" tabindex="-1">为什么会发生 <a class="header-anchor" href="#为什么会发生-1" aria-label="Permalink to &quot;为什么会发生&quot;">​</a></h3><ul><li>缺少明确的下一步判断</li><li>模型没有把“工具结果”纳入后续推理</li></ul><h3 id="后果-1" tabindex="-1">后果 <a class="header-anchor" href="#后果-1" aria-label="Permalink to &quot;后果&quot;">​</a></h3><ul><li>工具白调了</li><li>回答看起来像在乱做</li></ul><h2 id="问题-3-循环停不下来" tabindex="-1">问题 3：循环停不下来 <a class="header-anchor" href="#问题-3-循环停不下来" aria-label="Permalink to &quot;问题 3：循环停不下来&quot;">​</a></h2><h3 id="是什么-2" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-2" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>Agent 一直继续：</p><ul><li>再查一次</li><li>再试一个工具</li><li>再补一步</li></ul><p>结果迟迟不结束。</p><h3 id="为什么会发生-2" tabindex="-1">为什么会发生 <a class="header-anchor" href="#为什么会发生-2" aria-label="Permalink to &quot;为什么会发生&quot;">​</a></h3><ul><li>没有清晰的完成条件</li><li>模型过度谨慎</li><li>任务目标太模糊</li></ul><h3 id="后果-2" tabindex="-1">后果 <a class="header-anchor" href="#后果-2" aria-label="Permalink to &quot;后果&quot;">​</a></h3><ul><li>成本升高</li><li>延迟变长</li><li>用户体验很差</li></ul><h2 id="问题-4-本来该用-workflow-却硬上-agent" tabindex="-1">问题 4：本来该用 Workflow，却硬上 Agent <a class="header-anchor" href="#问题-4-本来该用-workflow-却硬上-agent" aria-label="Permalink to &quot;问题 4：本来该用 Workflow，却硬上 Agent&quot;">​</a></h2><h3 id="是什么-3" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-3" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>有些任务其实固定流程就够了， 但设计成了 Agent。</p><p>例如：</p><ul><li>每次都固定“查 -&gt; 总结 -&gt; 输出”</li><li>根本不需要动态决策</li></ul><h3 id="为什么会发生-3" tabindex="-1">为什么会发生 <a class="header-anchor" href="#为什么会发生-3" aria-label="Permalink to &quot;为什么会发生&quot;">​</a></h3><ul><li>觉得 Agent 更高级</li><li>没分清“自动化”和“动态决策”</li></ul><h3 id="后果-3" tabindex="-1">后果 <a class="header-anchor" href="#后果-3" aria-label="Permalink to &quot;后果&quot;">​</a></h3><ul><li>系统更复杂</li><li>更难调试</li><li>更不稳定</li></ul><h2 id="问题-5-工具太多-决策变乱" tabindex="-1">问题 5：工具太多，决策变乱 <a class="header-anchor" href="#问题-5-工具太多-决策变乱" aria-label="Permalink to &quot;问题 5：工具太多，决策变乱&quot;">​</a></h2><h3 id="是什么-4" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-4" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>给 Agent 太多工具，模型反而不容易选对。</p><h3 id="为什么会发生-4" tabindex="-1">为什么会发生 <a class="header-anchor" href="#为什么会发生-4" aria-label="Permalink to &quot;为什么会发生&quot;">​</a></h3><ul><li>工具描述太像</li><li>工具功能重复</li><li>模型决策空间过大</li></ul><h3 id="后果-4" tabindex="-1">后果 <a class="header-anchor" href="#后果-4" aria-label="Permalink to &quot;后果&quot;">​</a></h3><ul><li>工具切换混乱</li><li>错误率上升</li></ul><h2 id="问题-6-目标太模糊" tabindex="-1">问题 6：目标太模糊 <a class="header-anchor" href="#问题-6-目标太模糊" aria-label="Permalink to &quot;问题 6：目标太模糊&quot;">​</a></h2><h3 id="是什么-5" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-5" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>用户目标或者系统目标说得不清楚， 导致 Agent 不知道什么叫“完成”。</p><h3 id="为什么会发生-5" tabindex="-1">为什么会发生 <a class="header-anchor" href="#为什么会发生-5" aria-label="Permalink to &quot;为什么会发生&quot;">​</a></h3><ul><li>任务定义太宽泛</li><li>没有输出要求</li></ul><h3 id="后果-5" tabindex="-1">后果 <a class="header-anchor" href="#后果-5" aria-label="Permalink to &quot;后果&quot;">​</a></h3><ul><li>循环过长</li><li>输出不稳定</li><li>做了很多无关动作</li></ul><h2 id="问题-7-过度相信模型会自己规划好一切" tabindex="-1">问题 7：过度相信模型会自己规划好一切 <a class="header-anchor" href="#问题-7-过度相信模型会自己规划好一切" aria-label="Permalink to &quot;问题 7：过度相信模型会自己规划好一切&quot;">​</a></h2><h3 id="是什么-6" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-6" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>以为只要给模型很多工具， 它就会自然稳定地完成复杂任务。</p><h3 id="为什么会发生-6" tabindex="-1">为什么会发生 <a class="header-anchor" href="#为什么会发生-6" aria-label="Permalink to &quot;为什么会发生&quot;">​</a></h3><ul><li>对 Agent 的能力预期过高</li><li>缺少约束和边界设计</li></ul><h3 id="后果-6" tabindex="-1">后果 <a class="header-anchor" href="#后果-6" aria-label="Permalink to &quot;后果&quot;">​</a></h3><ul><li>结果随机性大</li><li>很难复现</li><li>一会儿对，一会儿错</li></ul><h2 id="初学时怎么避免" tabindex="-1">初学时怎么避免 <a class="header-anchor" href="#初学时怎么避免" aria-label="Permalink to &quot;初学时怎么避免&quot;">​</a></h2><p>建议你记住这 5 条：</p><ol><li>工具不要一开始给太多</li><li>工具描述要清楚</li><li>任务目标要具体</li><li>完成条件要明确</li><li>能用 Workflow 解决的，不要先上 Agent</li></ol><h2 id="最容易踩坑的一句总结" tabindex="-1">最容易踩坑的一句总结 <a class="header-anchor" href="#最容易踩坑的一句总结" aria-label="Permalink to &quot;最容易踩坑的一句总结&quot;">​</a></h2><p><code>不要把“模型会思考”误解成“模型会稳定执行任务”。</code></p><p>这是 Agent 入门最重要的现实认知之一。</p><h2 id="这一课你必须记住-7" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-7" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>Agent 难点在稳定执行，不只在回答</li><li>工具选择、结果利用、停止条件都很关键</li><li>并不是所有自动化都适合做 Agent</li><li>简单、可控、可观察，通常比“更智能”更重要</li></ul><h2 id="复习问题-7" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-7" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>Agent 为什么容易选错工具？</li><li>为什么“调了工具”不等于“真正用了工具结果”？</li><li>为什么没有完成条件时，Agent 容易停不下来？</li><li>为什么很多任务其实更适合 Workflow？</li></ol><h2 id="动手目标-7" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-7" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己说出 3 个你觉得 Agent 最容易出问题的点，并解释为什么。</p><hr><h2 id="第-9-步-agent-和-rag、workflow、tool、mcp-的总对比" tabindex="-1">第 9 步：Agent 和 RAG、Workflow、Tool、MCP 的总对比 <a class="header-anchor" href="#第-9-步-agent-和-rag、workflow、tool、mcp-的总对比" aria-label="Permalink to &quot;第 9 步：Agent 和 RAG、Workflow、Tool、MCP 的总对比&quot;">​</a></h2><h1 id="第-9-步-agent-和-rag、workflow、tool、mcp-的总对比-1" tabindex="-1">第 9 步：Agent 和 RAG、Workflow、Tool、MCP 的总对比 <a class="header-anchor" href="#第-9-步-agent-和-rag、workflow、tool、mcp-的总对比-1" aria-label="Permalink to &quot;第 9 步：Agent 和 RAG、Workflow、Tool、MCP 的总对比&quot;">​</a></h1><h2 id="学习目标-8" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标-8" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>把这些概念一次性理顺：</p><ul><li>Agent</li><li>RAG</li><li>Workflow</li><li>Tool</li><li>MCP</li></ul><h2 id="先记住一句话-7" tabindex="-1">先记住一句话 <a class="header-anchor" href="#先记住一句话-7" aria-label="Permalink to &quot;先记住一句话&quot;">​</a></h2><p><code>这几个词不在同一层。</code></p><p>它们分别属于：</p><ul><li>方法</li><li>系统形态</li><li>流程设计</li><li>能力组件</li><li>接入协议</li></ul><p>所以很多人会混淆，是因为它们在一个系统里经常同时出现。</p><h2 id="_1-rag-是什么" tabindex="-1">1. RAG 是什么 <a class="header-anchor" href="#_1-rag-是什么" aria-label="Permalink to &quot;1. RAG 是什么&quot;">​</a></h2><p><code>RAG = 先检索资料，再生成回答的方法</code></p><p>它的重点是：</p><ul><li>查资料</li><li>用资料回答</li></ul><p>它回答的是：</p><p><code>知识从哪里来</code></p><h2 id="_2-agent-是什么" tabindex="-1">2. Agent 是什么 <a class="header-anchor" href="#_2-agent-是什么" aria-label="Permalink to &quot;2. Agent 是什么&quot;">​</a></h2><p><code>Agent = 为了完成目标，自己决定步骤并调用工具的系统</code></p><p>它的重点是：</p><ul><li>有目标</li><li>会判断下一步</li><li>会调用工具</li><li>会多步推进</li></ul><p>它回答的是：</p><p><code>任务怎么一步步完成</code></p><h2 id="_3-workflow-是什么" tabindex="-1">3. Workflow 是什么 <a class="header-anchor" href="#_3-workflow-是什么" aria-label="Permalink to &quot;3. Workflow 是什么&quot;">​</a></h2><p><code>Workflow = 预先设计好的固定流程</code></p><p>它的重点是：</p><ul><li>步骤提前定义</li><li>顺序基本固定</li><li>系统自己决定空间小</li></ul><p>它回答的是：</p><p><code>流程怎么固定执行</code></p><h2 id="_4-tool-是什么" tabindex="-1">4. Tool 是什么 <a class="header-anchor" href="#_4-tool-是什么" aria-label="Permalink to &quot;4. Tool 是什么&quot;">​</a></h2><p><code>Tool = Agent 或模型可调用的具体外部能力</code></p><p>例如：</p><ul><li>读文件</li><li>搜网页</li><li>查数据库</li><li>调 RAG</li><li>执行代码</li></ul><p>它回答的是：</p><p><code>系统具体能做什么动作</code></p><h2 id="_5-mcp-是什么" tabindex="-1">5. MCP 是什么 <a class="header-anchor" href="#_5-mcp-是什么" aria-label="Permalink to &quot;5. MCP 是什么&quot;">​</a></h2><p><code>MCP = 让模型或 Agent 接入外部能力的一种标准协议</code></p><p>它的重点是：</p><ul><li>统一接入</li><li>统一暴露工具和资源</li><li>统一调用方式</li></ul><p>它回答的是：</p><p><code>这些能力怎么标准化接进来</code></p><h2 id="放到一张脑图里" tabindex="-1">放到一张脑图里 <a class="header-anchor" href="#放到一张脑图里" aria-label="Permalink to &quot;放到一张脑图里&quot;">​</a></h2><p>你可以这样理解：</p><ul><li><code>RAG</code>：一种知识获取与回答方法</li><li><code>Agent</code>：一种会动态决策的系统形态</li><li><code>Workflow</code>：一种固定流程组织方式</li><li><code>Tool</code>：具体可调用能力</li><li><code>MCP</code>：把 Tool 接给模型/Agent 的协议层</li></ul><h2 id="它们之间怎么相互关系" tabindex="-1">它们之间怎么相互关系 <a class="header-anchor" href="#它们之间怎么相互关系" aria-label="Permalink to &quot;它们之间怎么相互关系&quot;">​</a></h2><h3 id="agent-和-rag" tabindex="-1">Agent 和 RAG <a class="header-anchor" href="#agent-和-rag" aria-label="Permalink to &quot;Agent 和 RAG&quot;">​</a></h3><ul><li>RAG 不等于 Agent</li><li>Agent 也不等于 RAG</li><li>但 Agent 可以把 RAG 当成一个工具</li></ul><h3 id="agent-和-workflow" tabindex="-1">Agent 和 Workflow <a class="header-anchor" href="#agent-和-workflow" aria-label="Permalink to &quot;Agent 和 Workflow&quot;">​</a></h3><ul><li>Workflow 是固定流程</li><li>Agent 是动态决策</li><li>实际系统里经常混合使用</li></ul><h3 id="agent-和-tool" tabindex="-1">Agent 和 Tool <a class="header-anchor" href="#agent-和-tool" aria-label="Permalink to &quot;Agent 和 Tool&quot;">​</a></h3><ul><li>Tool 是 Agent 做事的手和脚</li><li>没有 Tool，Agent 往往只能“说”，不能真正“做”</li></ul><h3 id="tool-和-mcp" tabindex="-1">Tool 和 MCP <a class="header-anchor" href="#tool-和-mcp" aria-label="Permalink to &quot;Tool 和 MCP&quot;">​</a></h3><ul><li>Tool 是具体能力</li><li>MCP 是接入这些能力的协议标准</li></ul><h3 id="rag-和-tool" tabindex="-1">RAG 和 Tool <a class="header-anchor" href="#rag-和-tool" aria-label="Permalink to &quot;RAG 和 Tool&quot;">​</a></h3><ul><li>在 Agent 系统里，RAG 常常会被包装成一个 Tool</li></ul><h2 id="一个非常实用的判断表" tabindex="-1">一个非常实用的判断表 <a class="header-anchor" href="#一个非常实用的判断表" aria-label="Permalink to &quot;一个非常实用的判断表&quot;">​</a></h2><h3 id="如果你问的是" tabindex="-1">如果你问的是： <a class="header-anchor" href="#如果你问的是" aria-label="Permalink to &quot;如果你问的是：&quot;">​</a></h3><p>“知识从哪里来？”</p><p>更像在谈：</p><ul><li><code>RAG</code></li></ul><h3 id="如果你问的是-1" tabindex="-1">如果你问的是： <a class="header-anchor" href="#如果你问的是-1" aria-label="Permalink to &quot;如果你问的是：&quot;">​</a></h3><p>“任务怎么一步步自己完成？”</p><p>更像在谈：</p><ul><li><code>Agent</code></li></ul><h3 id="如果你问的是-2" tabindex="-1">如果你问的是： <a class="header-anchor" href="#如果你问的是-2" aria-label="Permalink to &quot;如果你问的是：&quot;">​</a></h3><p>“步骤是不是提前写死？”</p><p>更像在谈：</p><ul><li><code>Workflow</code></li></ul><h3 id="如果你问的是-3" tabindex="-1">如果你问的是： <a class="header-anchor" href="#如果你问的是-3" aria-label="Permalink to &quot;如果你问的是：&quot;">​</a></h3><p>“系统具体能调什么能力？”</p><p>更像在谈：</p><ul><li><code>Tool</code></li></ul><h3 id="如果你问的是-4" tabindex="-1">如果你问的是： <a class="header-anchor" href="#如果你问的是-4" aria-label="Permalink to &quot;如果你问的是：&quot;">​</a></h3><p>“这些能力怎么统一接给模型？”</p><p>更像在谈：</p><ul><li><code>MCP</code></li></ul><h2 id="最容易混淆的地方" tabindex="-1">最容易混淆的地方 <a class="header-anchor" href="#最容易混淆的地方" aria-label="Permalink to &quot;最容易混淆的地方&quot;">​</a></h2><h3 id="误区-1" tabindex="-1">误区 1 <a class="header-anchor" href="#误区-1" aria-label="Permalink to &quot;误区 1&quot;">​</a></h3><p>“RAG 就是 Agent”</p><p>错。</p><p>RAG 是方法，Agent 是系统形态。</p><h3 id="误区-2" tabindex="-1">误区 2 <a class="header-anchor" href="#误区-2" aria-label="Permalink to &quot;误区 2&quot;">​</a></h3><p>“自动化流程就是 Agent”</p><p>错。</p><p>固定步骤更可能只是 Workflow。</p><h3 id="误区-3" tabindex="-1">误区 3 <a class="header-anchor" href="#误区-3" aria-label="Permalink to &quot;误区 3&quot;">​</a></h3><p>“MCP 就是工具”</p><p>错。</p><p>MCP 更像工具接入协议。</p><h3 id="误区-4" tabindex="-1">误区 4 <a class="header-anchor" href="#误区-4" aria-label="Permalink to &quot;误区 4&quot;">​</a></h3><p>“有很多工具就一定是好 Agent”</p><p>错。</p><p>工具太多反而更容易让 Agent 决策混乱。</p><h2 id="一句话总总结" tabindex="-1">一句话总总结 <a class="header-anchor" href="#一句话总总结" aria-label="Permalink to &quot;一句话总总结&quot;">​</a></h2><p>你可以这样把它们压缩记住：</p><ul><li><code>RAG</code> 管知识</li><li><code>Agent</code> 管决策</li><li><code>Workflow</code> 管固定流程</li><li><code>Tool</code> 管行动能力</li><li><code>MCP</code> 管接入标准</li></ul><h2 id="这一课你必须记住-8" tabindex="-1">这一课你必须记住 <a class="header-anchor" href="#这一课你必须记住-8" aria-label="Permalink to &quot;这一课你必须记住&quot;">​</a></h2><ul><li>这些概念不在同一层</li><li>一个真实系统里，它们常常会同时出现</li><li>先分清层次，再谈怎么组合</li></ul><h2 id="复习问题-8" tabindex="-1">复习问题 <a class="header-anchor" href="#复习问题-8" aria-label="Permalink to &quot;复习问题&quot;">​</a></h2><ol><li>为什么说 RAG 和 Agent 不在同一层？</li><li>Workflow 和 Agent 最大区别是什么？</li><li>Tool 和 MCP 最大区别是什么？</li><li>为什么 RAG 在 Agent 系统里常常会变成一个 Tool？</li></ol><h2 id="动手目标-8" tabindex="-1">动手目标 <a class="header-anchor" href="#动手目标-8" aria-label="Permalink to &quot;动手目标&quot;">​</a></h2><p>请你自己用一句话分别解释：</p><ul><li><code>RAG 管什么</code></li><li><code>Agent 管什么</code></li><li><code>Workflow 管什么</code></li><li><code>Tool 管什么</code></li><li><code>MCP 管什么</code></li></ul><hr><h2 id="agent-总复习" tabindex="-1">Agent 总复习 <a class="header-anchor" href="#agent-总复习" aria-label="Permalink to &quot;Agent 总复习&quot;">​</a></h2><h1 id="agent-总复习-1" tabindex="-1">Agent 总复习 <a class="header-anchor" href="#agent-总复习-1" aria-label="Permalink to &quot;Agent 总复习&quot;">​</a></h1><p>这份文档只保留后期复习最重要的内容。</p><h2 id="一、agent-是什么" tabindex="-1">一、Agent 是什么 <a class="header-anchor" href="#一、agent-是什么" aria-label="Permalink to &quot;一、Agent 是什么&quot;">​</a></h2><p>最简单定义：</p><p><code>Agent = 为了完成目标，自己决定步骤并调用工具的系统</code></p><p>一句话记忆：</p><p><code>Agent 管的是“任务怎么一步步完成”。</code></p><h2 id="二、agent-和普通大模型调用的区别" tabindex="-1">二、Agent 和普通大模型调用的区别 <a class="header-anchor" href="#二、agent-和普通大模型调用的区别" aria-label="Permalink to &quot;二、Agent 和普通大模型调用的区别&quot;">​</a></h2><p>普通 LLM：</p><ul><li>你问一句</li><li>它答一句</li></ul><p>Agent：</p><ul><li>你给一个目标</li><li>它判断下一步</li><li>调工具</li><li>看结果</li><li>再判断</li><li>最后完成任务</li></ul><p>一句话记忆：</p><p><code>普通模型偏单次回答，Agent 偏多步执行。</code></p><h2 id="三、agent-最小系统需要什么" tabindex="-1">三、Agent 最小系统需要什么 <a class="header-anchor" href="#三、agent-最小系统需要什么" aria-label="Permalink to &quot;三、Agent 最小系统需要什么&quot;">​</a></h2><p>最小 Agent = 5 个部分：</p><ol><li>目标</li><li>大模型</li><li>工具</li><li>决策循环</li><li>输出</li></ol><p>一句话记忆：</p><p><code>目标 + 模型 + 工具 + 循环 + 输出</code></p><h2 id="四、agent-最小运行流程" tabindex="-1">四、Agent 最小运行流程 <a class="header-anchor" href="#四、agent-最小运行流程" aria-label="Permalink to &quot;四、Agent 最小运行流程&quot;">​</a></h2><p>最小运行流程：</p><ol><li>接收目标</li><li>判断下一步</li><li>调用工具</li><li>观察结果</li><li>再判断</li><li>输出结果</li></ol><p>Agent 的核心循环就是：</p><p><code>判断 -&gt; 行动 -&gt; 观察 -&gt; 再判断</code></p><h2 id="五、为什么-agent-需要工具" tabindex="-1">五、为什么 Agent 需要工具 <a class="header-anchor" href="#五、为什么-agent-需要工具" aria-label="Permalink to &quot;五、为什么 Agent 需要工具&quot;">​</a></h2><p>因为大模型最擅长的是：</p><ul><li>生成文本</li></ul><p>但真实任务还需要：</p><ul><li>读文件</li><li>搜网页</li><li>查数据库</li><li>调 RAG</li><li>执行代码</li></ul><p>没有工具，Agent 很多时候只能“说怎么做”，不能“真的做”。</p><p>一句话记忆：</p><p><code>工具负责行动，模型负责思考。</code></p><h2 id="六、工具是什么" tabindex="-1">六、工具是什么 <a class="header-anchor" href="#六、工具是什么" aria-label="Permalink to &quot;六、工具是什么&quot;">​</a></h2><p>工具就是：</p><p><code>Agent 可调用的外部能力</code></p><p>常见例子：</p><ul><li>文件读取</li><li>浏览器/搜索</li><li>数据库查询</li><li>RAG 检索器</li><li>代码执行器</li></ul><p>注意区分：</p><ul><li><code>读文件</code> 算工具</li><li><code>分析上下文</code> 不算工具，更像模型能力</li></ul><h2 id="七、workflow-是什么" tabindex="-1">七、Workflow 是什么 <a class="header-anchor" href="#七、workflow-是什么" aria-label="Permalink to &quot;七、Workflow 是什么&quot;">​</a></h2><p>最简单定义：</p><p><code>Workflow = 预先设计好的固定流程</code></p><p>一句话记忆：</p><ul><li><code>Workflow = 人定流程</code></li><li><code>Agent = 模型定下一步</code></li></ul><h2 id="八、mcp-是什么" tabindex="-1">八、MCP 是什么 <a class="header-anchor" href="#八、mcp-是什么" aria-label="Permalink to &quot;八、MCP 是什么&quot;">​</a></h2><p>如果说的是 <code>Model Context Protocol</code>：</p><p><code>MCP = 让模型或 Agent 接入外部工具和资源的标准协议</code></p><p>它不是具体工具。</p><p>一句话记忆：</p><ul><li><code>Tool = 具体能力</code></li><li><code>MCP = 接入标准</code></li></ul><h2 id="九、agent-的常见模式" tabindex="-1">九、Agent 的常见模式 <a class="header-anchor" href="#九、agent-的常见模式" aria-label="Permalink to &quot;九、Agent 的常见模式&quot;">​</a></h2><h3 id="_1-单工具-agent" tabindex="-1">1. 单工具 Agent <a class="header-anchor" href="#_1-单工具-agent" aria-label="Permalink to &quot;1. 单工具 Agent&quot;">​</a></h3><ul><li>只有一个主要工具</li></ul><h3 id="_2-多工具-agent" tabindex="-1">2. 多工具 Agent <a class="header-anchor" href="#_2-多工具-agent" aria-label="Permalink to &quot;2. 多工具 Agent&quot;">​</a></h3><ul><li>有多个工具可选</li></ul><h3 id="_3-rag-作为工具的-agent" tabindex="-1">3. RAG 作为工具的 Agent <a class="header-anchor" href="#_3-rag-作为工具的-agent" aria-label="Permalink to &quot;3. RAG 作为工具的 Agent&quot;">​</a></h3><ul><li>需要查知识时调用 RAG</li></ul><h3 id="_4-workflow-外壳-agent-核心" tabindex="-1">4. Workflow 外壳 + Agent 核心 <a class="header-anchor" href="#_4-workflow-外壳-agent-核心" aria-label="Permalink to &quot;4. Workflow 外壳 + Agent 核心&quot;">​</a></h3><ul><li>外层固定流程</li><li>局部动态决策</li></ul><h3 id="_5-纯-workflow-不是真正-agent" tabindex="-1">5. 纯 Workflow，不是真正 Agent <a class="header-anchor" href="#_5-纯-workflow-不是真正-agent" aria-label="Permalink to &quot;5. 纯 Workflow，不是真正 Agent&quot;">​</a></h3><ul><li>步骤固定</li><li>没有动态选择下一步</li></ul><h2 id="十、最容易混淆的地方" tabindex="-1">十、最容易混淆的地方 <a class="header-anchor" href="#十、最容易混淆的地方" aria-label="Permalink to &quot;十、最容易混淆的地方&quot;">​</a></h2><h3 id="_1-agent-和-workflow" tabindex="-1">1. Agent 和 Workflow <a class="header-anchor" href="#_1-agent-和-workflow" aria-label="Permalink to &quot;1. Agent 和 Workflow&quot;">​</a></h3><p>Workflow：</p><ul><li>固定步骤</li><li>不强调动态决策</li></ul><p>Agent：</p><ul><li>会根据目标和中间结果决定下一步</li></ul><p>一句话记忆：</p><ul><li><code>固定步骤 = 更像 Workflow</code></li><li><code>动态决策 = 更像 Agent</code></li></ul><h3 id="_2-agent-和-rag" tabindex="-1">2. Agent 和 RAG <a class="header-anchor" href="#_2-agent-和-rag" aria-label="Permalink to &quot;2. Agent 和 RAG&quot;">​</a></h3><p>RAG：</p><ul><li>先检索再回答的方法</li></ul><p>Agent：</p><ul><li>为了完成目标动态决策的系统</li></ul><p>关系：</p><ul><li>RAG 可以成为 Agent 的一个工具</li></ul><p>一句话记忆：</p><ul><li><code>RAG 管知识</code></li><li><code>Agent 管决策</code></li></ul><h3 id="_3-tool-和-mcp" tabindex="-1">3. Tool 和 MCP <a class="header-anchor" href="#_3-tool-和-mcp" aria-label="Permalink to &quot;3. Tool 和 MCP&quot;">​</a></h3><p>Tool：</p><ul><li>具体能力</li></ul><p>MCP：</p><ul><li>让这些能力标准化接进模型/Agent 的协议</li></ul><p>一句话记忆：</p><ul><li><code>工具像电器</code></li><li><code>MCP 像插座标准</code></li></ul><h2 id="十一、agent-最容易出问题的地方" tabindex="-1">十一、Agent 最容易出问题的地方 <a class="header-anchor" href="#十一、agent-最容易出问题的地方" aria-label="Permalink to &quot;十一、Agent 最容易出问题的地方&quot;">​</a></h2><p>最常见问题：</p><ul><li>选错工具</li><li>调了工具但不会用结果</li><li>循环停不下来</li><li>本来该用 Workflow，却硬上 Agent</li><li>工具太多，决策变乱</li><li>目标太模糊</li><li>过度相信模型会自己规划好一切</li></ul><p>一句话记忆：</p><p><code>Agent 最大的问题通常不是不会说，而是不会稳定地做事。</code></p><p>最该刻进脑子的一句：</p><p><code>不要把“模型会思考”误解成“模型会稳定执行任务”。</code></p><h2 id="十一-a、初学避坑-5-条" tabindex="-1">十一-A、初学避坑 5 条 <a class="header-anchor" href="#十一-a、初学避坑-5-条" aria-label="Permalink to &quot;十一-A、初学避坑 5 条&quot;">​</a></h2><ol><li>工具不要一开始给太多</li><li>工具描述要清楚</li><li>任务目标要具体</li><li>完成条件要明确（这是“循环停不下来”的解药）</li><li>能用 Workflow 解决的，不要先上 Agent</li></ol><p>一句话记忆：</p><p><code>简单、可控、可观察，通常比“更智能”更重要。</code></p><h2 id="十二、什么时候更适合-workflow-不适合-agent" tabindex="-1">十二、什么时候更适合 Workflow，不适合 Agent <a class="header-anchor" href="#十二、什么时候更适合-workflow-不适合-agent" aria-label="Permalink to &quot;十二、什么时候更适合 Workflow，不适合 Agent&quot;">​</a></h2><p>如果任务是：</p><ul><li>固定步骤</li><li>重复执行</li><li>不需要动态决策</li></ul><p>那通常更适合 Workflow。</p><p>一句话记忆：</p><p><code>能用固定流程解决的，就不要先用 Agent。</code></p><h2 id="十三、后期复习只记这些句子" tabindex="-1">十三、后期复习只记这些句子 <a class="header-anchor" href="#十三、后期复习只记这些句子" aria-label="Permalink to &quot;十三、后期复习只记这些句子&quot;">​</a></h2><ul><li><code>Agent = 为完成目标，自己决定步骤并调用工具</code></li><li><code>Agent 管决策</code></li><li><code>工具负责行动，模型负责思考</code></li><li><code>Workflow 是固定流程</code></li><li><code>MCP 是工具接入标准，不是工具本身</code></li><li><code>RAG 可以是 Agent 的工具</code></li><li><code>固定步骤更像 Workflow，动态决策更像 Agent</code></li><li><code>Agent 最大问题是稳定执行，不只是回答</code></li><li><code>不要把“会思考”误解成“会稳定执行”</code></li><li><code>完成条件要明确，否则循环停不下来</code></li><li><code>能用 Workflow 解决的，就不要先上 Agent</code></li></ul>',817)])])}const s=a(o,[["render",r]]);export{p as __pageData,s as default};
